fr_single_re = re.compile(r'FR-(\d{3})')
fr_range_re = re.compile(r'FR-(\d{3})\s*(?:to|-)\s*FR-(\d{3})', re.IGNORECASE)

explicit_refs = defaultdict(list)
for t in tasks:
    text = t['title'] + "\n" + "\n".join(t['lines'])
