    for start, end in fr_range_re.findall(text):
        s = int(start); e = int(end)
        if s <= e:
            fr_refs.extend([f"FR-{i:03d}" for i in range(s, e+1)])
        else:
            fr_refs.extend([f"FR-{i:03d}" for i in range(e, s+1)])
    fr_refs.extend([f"FR-{m}" for m in fr_single_re.findall(text)])
    # dedupe
    seen=set(); uniq=[]
    for fr in fr_refs:
        if fr not in seen:
