def slugify(text, max_words=8):
    text = text.strip()
    if re.match(r'^System MUST NOT\b', text, flags=re.IGNORECASE):
        text = re.sub(r'^System MUST NOT\s+','not ', text, flags=re.IGNORECASE)
    else:
        text = re.sub(r'^System MUST\s+','', text, flags=re.IGNORECASE)
    text = re.sub(r'\(.*?\)','', text)
    text = text.replace('"', '')
    text = re.sub(r'[^A-Za-z0-9]+', ' ', text)
    words = [w.lower() for w in text.split() if w]
    words = words[:max_words]
